#!/usr/bin/env node
// Generates the leaves' look (docs/TREE_GROWTH.md §10) for Rust (crates/dwell-look/src/leaves.gen.rs)
// from shared/look/leaves.json, after validating it: an unknown, missing or out-of-range entry fails
// with its path named. The output is checked in; CI regenerates it and fails on any diff.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..", "..");
const header =
  "Generated by shared/look/leaves.mjs from shared/look/leaves.json. Do not edit.";

const fail = (m) => {
  throw new Error(`leaves.json: ${m}`);
};

function checkKeys(where, obj, keys) {
  if (typeof obj !== "object" || obj === null || Array.isArray(obj))
    fail(`${where} must be an object`);
  for (const k of Object.keys(obj)) {
    if (k !== "$comment" && !keys.includes(k))
      fail(`unknown entry ${where}.${k}`);
  }
  for (const k of keys) if (!(k in obj)) fail(`missing entry ${where}.${k}`);
}

function checkNumber(where, v, lo, hi) {
  if (typeof v !== "number" || !Number.isFinite(v) || v < lo || v > hi) {
    fail(
      `${where} must be a number in [${lo}, ${hi}], got ${JSON.stringify(v)}`,
    );
  }
}

/** The renderer's tiers (`dwell-client` `render::cards_for`), each with its own switch. */
const TIERS = ["desktop", "phone", "cpu"];

/** Checks the look; returns it. Throws naming the entry. */
export function validateLeaves(data) {
  checkKeys("(root)", data, ["blocks", "canopyBlend", "chamfer", "cards"]);
  if (!Array.isArray(data.blocks) || data.blocks.length === 0)
    fail("blocks must list at least one block");
  data.blocks.forEach((b, i) => {
    if (typeof b !== "string" || !/^[a-z0-9_]+:[a-z0-9_]+$/.test(b)) {
      fail(
        `blocks[${i}] must be a block name (namespace:name), got ${JSON.stringify(b)}`,
      );
    }
    if (data.blocks.indexOf(b) !== i) fail(`blocks[${i}] repeats ${b}`);
  });
  checkNumber("canopyBlend", data.canopyBlend, 0, 1);
  // Past 0.45 an edge's cut meets the opposite edge's in a one-cell-thick layer of leaves.
  checkNumber("chamfer", data.chamfer, 0, 0.45);
  const c = data.cards;
  checkKeys("cards", c, [
    "tile",
    "density",
    "sizeM",
    "swayM",
    "fadeStartM",
    "fadeEndM",
    "interiorCells",
    "backCullM",
    "tiers",
  ]);
  if (typeof c.tile !== "string" || !/^[A-Za-z0-9_]+$/.test(c.tile))
    fail(`cards.tile must be a tile name, got ${JSON.stringify(c.tile)}`);
  checkNumber("cards.density", c.density, 0, 4);
  checkNumber("cards.sizeM", c.sizeM, 0.1, 3);
  checkNumber("cards.swayM", c.swayM, 0, 0.5);
  checkNumber("cards.fadeStartM", c.fadeStartM, 0, 512);
  checkNumber("cards.fadeEndM", c.fadeEndM, c.fadeStartM + 1, 1024);
  if (
    !Number.isInteger(c.interiorCells) ||
    c.interiorCells < 0 ||
    c.interiorCells > 8
  )
    fail(
      `cards.interiorCells must be a whole number in [0, 8], got ${JSON.stringify(c.interiorCells)}`,
    );
  checkNumber("cards.backCullM", c.backCullM, 0, 64);
  checkKeys("cards.tiers", c.tiers, TIERS);
  for (const t of TIERS) {
    if (typeof c.tiers[t] !== "boolean")
      fail(
        `cards.tiers.${t} must be true or false, got ${JSON.stringify(c.tiers[t])}`,
      );
  }
  return data;
}

const rf = (v) => (Number.isInteger(v) ? `${v}.0` : `${v}`);

/** The Rust source for a validated look. */
export function leavesRust(data) {
  return [
    `// ${header}`,
    "",
    "use crate::leaves::{CardTiers, LeafCards, LeavesLook};",
    "",
    "/// The leaves' look (shared/look/leaves.json).",
    "pub const LEAVES: LeavesLook = LeavesLook {",
    `    blocks: &[${data.blocks.map((b) => JSON.stringify(b)).join(", ")}],`,
    `    canopy_blend: ${rf(data.canopyBlend)},`,
    `    chamfer: ${rf(data.chamfer)},`,
    "    cards: LeafCards {",
    `        tile: ${JSON.stringify(data.cards.tile)},`,
    `        density: ${rf(data.cards.density)},`,
    `        size_m: ${rf(data.cards.sizeM)},`,
    `        sway_m: ${rf(data.cards.swayM)},`,
    `        fade_start_m: ${rf(data.cards.fadeStartM)},`,
    `        fade_end_m: ${rf(data.cards.fadeEndM)},`,
    `        interior_cells: ${data.cards.interiorCells},`,
    `        back_cull_m: ${rf(data.cards.backCullM)},`,
    "        tiers: CardTiers {",
    ...TIERS.map((t) => `            ${t}: ${data.cards.tiers[t]},`),
    "        },",
    "    },",
    "};",
    "",
  ].join("\n");
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  const data = validateLeaves(
    JSON.parse(readFileSync(join(here, "leaves.json"), "utf8")),
  );
  writeFileSync(
    join(root, "crates/dwell-look/src/leaves.gen.rs"),
    leavesRust(data),
  );
  console.log("look: the leaves' look generated");
}
